#!/usr/bin/env Rscript
# Independent read-back verifier for the locked trial-level model outputs.
suppressPackageStartupMessages({library(lme4);library(lmerTest);library(jsonlite)})
OUT <- paste0(Sys.getenv("DMN_PROJECT_ROOT", unset = normalizePath(getwd(), mustWork = TRUE)), "/manuscript/paper2_dmn-connectivity/revision-1/R1/review_round2/spatial_learning_dmn_v1/trial_model")
ROOT <- Sys.getenv("DMN_PROJECT_ROOT", unset = normalizePath(getwd(), mustWork = TRUE))
NEURAL <- file.path(ROOT,'manuscript/paper2_dmn-connectivity/revision-1/R1/review_round2/resolved_reanalysis/extraction_common_coverage/participant_scores_resolved.csv')
TRIALS <- file.path(ROOT,'manuscript/paper2_dmn-connectivity/revision-1/attached-v3-correct-rt/brain_behavior/correct_rt_trials_n33.csv')
sha <- function(p) unname(system2('sha256sum',p,stdout=TRUE) |> strsplit(' +') |> lapply(`[[`,1) |> unlist())
need <- c('exact_model_frame.csv','final_selected_model.rds','final_selected_fixed_effects.csv','final_selected_random_covariance.csv','final_selected_subject_random_effects.csv','final_selected_neural_location_contrasts_Holm4.csv','source_and_coding_audit.csv','optimizer_diagnostics_summary.csv','verification.json')
stopifnot(all(file.exists(file.path(OUT,need))))
expected_hashes <- c(neural='cc3cddf8377ff9aefba18e8781d2512151e335f280d232c5b23d791266e6feef',trials='fac39301cb3b828f925937e080213bc5ed39fcaa03cbe0e6c558cf2ea18b34c6')
actual_hashes <- c(neural=sha(NEURAL),trials=sha(TRIALS))
stopifnot(identical(unname(actual_hashes),unname(expected_hashes)))
d <- read.csv(file.path(OUT,'exact_model_frame.csv'),check.names=FALSE)
fit <- readRDS(file.path(OUT,'final_selected_model.rds'))
expected_formula <- RT100 ~ L*X*D + run2 + L:run2 + (1+L|subject)
formula_ok <- identical(deparse(formula(fit)),deparse(expected_formula))
stopifnot(formula_ok, nrow(d)==6721L, length(unique(d$subject))==33L, all(d$category=='biased'),all(d$L %in% 0:1),all(d$run2 %in% 0:1))
mf <- model.frame(fit)
frame_fit_agree <- nrow(mf)==nrow(d) && isTRUE(all.equal(as.numeric(mf$RT100),d$RT100,tolerance=1e-12)) && all(as.numeric(mf$L)==d$L) && isTRUE(all.equal(as.numeric(mf$X),d$X,tolerance=1e-12)) && all(as.numeric(mf$D)==d$D) && all(as.numeric(mf$run2)==d$run2) && identical(as.character(mf$subject),as.character(d$subject))
stopifnot(frame_fit_agree, isREML(fit))
fixed <- read.csv(file.path(OUT,'final_selected_fixed_effects.csv'),check.names=FALSE)
sm <- summary(fit)$coefficients
fixed_ok <- identical(fixed$term,rownames(sm)) && max(abs(fixed$estimate_RT100-sm[,'Estimate']))<1e-10 && max(abs(fixed$SE_RT100-sm[,'Std. Error']))<1e-10
stopifnot(fixed_ok)
canon <- function(x)paste(sort(strsplit(x,':',fixed=TRUE)[[1]]),collapse=':')
con <- function(w) {v<-setNames(rep(0,length(fixef(fit))),names(fixef(fit)));for(z in names(w)){i<-which(vapply(names(v),canon,'')==canon(z));stopifnot(length(i)==1L);v[i]<-w[[z]]};as.data.frame(contest1D(fit,v,confint=TRUE,ddf='Satterthwaite'))}
cc <- list(con(list('L:X'=1,'L:X:D'=17/33)),con(list('L:X'=1)),con(list('L:X'=1,'L:X:D'=1)),con(list('L:X:D'=1)))
ct <- read.csv(file.path(OUT,'final_selected_neural_location_contrasts_Holm4.csv'),check.names=FALSE)
contrast_ok <- nrow(ct)==4L && max(abs(ct$estimate_RT100-vapply(cc,function(z)z$Estimate,numeric(1))))<1e-10 && max(abs(ct$p_raw-vapply(cc,function(z)z[['Pr(>|t|)']],numeric(1))))<1e-12 && max(abs(ct$p_Holm4-p.adjust(ct$p_raw,'holm')))<1e-12 && all(grepl('ms per global SD',ct$unit,fixed=TRUE)) && all(grepl('larger Rare-minus-Frequent',ct$positive_sign_interpretation,fixed=TRUE))
stopifnot(contrast_ok)
audit <- read.csv(file.path(OUT,'source_and_coding_audit.csv')); optimizer <- read.csv(file.path(OUT,'optimizer_diagnostics_summary.csv'),check.names=FALSE)
stopifnot(all(audit$pass),nrow(optimizer)==5L,all(optimizer$REML),all(!optimizer$isSingular_tol1e4),all(is.finite(optimizer$logLik)))
manifest <- fromJSON(file.path(OUT,'verification.json'))
frame_hash_ok <- identical(sha(file.path(OUT,'exact_model_frame.csv')),manifest$exact_model_frame_sha256)
stopifnot(frame_hash_ok)
result <- list(status='PASS',independent_readback=TRUE,source_hashes=as.list(actual_hashes),checks=list(formula_ok=formula_ok,REML=TRUE,exact_frame_fit_agreement=frame_fit_agree,fixed_effects_reproduced=fixed_ok,four_contrasts_reproduced=contrast_ok,Holm4_reproduced=contrast_ok,source_coding_audit_pass=all(audit$pass),optimizer_records=as.integer(nrow(optimizer)),all_correlated_fits_nonsingular=all(!optimizer$isSingular_tol1e4),frame_hash_matches_manifest=frame_hash_ok),recomputed=list(model_rows=nrow(d),participants=length(unique(d$subject)),contrast_estimate_ms=as.list(ct$estimate_ms_per_global_corrected_DMN_SD),contrast_Holm4_p=as.list(ct$p_Holm4)))
write_json(result,file.path(OUT,'verification_independent.json'),pretty=TRUE,auto_unbox=TRUE)
cat(sprintf('PASS independent verifier: %d rows, %d participants, four contrasts and Holm4 reproduced.\n',nrow(d),length(unique(d$subject))))
